<template>
	<view class="userinfo">

		<view class="main">
			<view class="form">
				<!-- 				<view class="form-item flex justify-between align-start">
					<view class="form-label">
						<text>*</text>头像
					</view>
					<view class="form-value flex justify-end">
						<view class="img-box" @click="upImg(2)">
							<image :src="imgurl + form.head_img" mode="aspectFit" v-if="form.head_img"></image>
							<text class="iconfont icon-a-fenzu1" v-else></text>
						</view>
					</view>
				</view> -->

				<view class="form-item flex justify-start align-center">
					<view class="form-label">
						<text>*</text>学员姓名
					</view>
					<view class="form-value">
						<input type="text" v-model="form.realname" placeholder="点击输入姓名" class="input">
					</view>
				</view>

				<!-- 				<view class="form-item flex justify-start align-center">
					<view class="form-label">
						<text>*</text>手机号码
					</view>
					<view class="form-value">
						<input type="text" v-model="form.phone" disabled class="input">
					</view>
				</view> -->
			</view>
		</view>
		<view class="btnbox flex justify-center align-center">
			<view class="btn" @click="sub">保存修改</view>
			<view class="btn" @click="signOut">退出登录</view>
		</view>
	</view>
</template>
<script>
	import {
		loaded,
		loading,
		toast,
		redirectTo,
		navigateTo,
		userLogout,
		navigateBack
	} from '@/utils/index.js';
	import {
		img_PATH
	} from '@/config';
	import {
		uploadFile
	} from '@/api/upload.js';
	import {
		getUserInfo,
		saveUserInfo
	} from '@/api'
	export default {
		data() {
			return {
				imgurl: img_PATH,
				CustomBar: this.CustomBar,
				showLoading: false,
				showNone: false,
				form: {
					head_img: '',
					realname: '',
					phone: ''
				}
			};
		},
		computed: {

		},
		components: {

		},
		onLoad() {

		},
		created() {
			this.getInfo()
		},
		// 触底的事件
		onReachBottom() {

		},
		methods: {

			async getInfo() {
				let _res = await getUserInfo();
				if (_res.code == 200) {
					this.form = {
						head_img: _res.data.picPath,
						realname: _res.data.userName,
						phone: _res.data.loginCode
					}
					this.userInfo = _res.data
				}
			},

			async sub() {
				if (!this.form.realname) return toast('请输入学员姓名')
				loading()
				let _data = await saveUserInfo(
					this.form.picPath,
					this.form.realname,
					3, 0
				);
				loaded()
				if (_data.code == 200) {
					toast(_data.msg)
					navigateBack()
				} else {
					toast(_data.msg)
				}
			},

			signOut() {
				userLogout()
			},

			// 图片上传
			upImg(type) {
				var that = this
				uni.chooseImage({
					count: 1, // 图片数量
					sizeType: ['original', 'compressed'], //可以指定是原图还是压缩图，默认二者都有
					sourceType: ['album', 'camera'], //从相册选择或者拍照
					success: (res) => {
						let tempStr = res.tempFilePaths[0].split('.');
						let lowerStr = tempStr[1].toLowerCase();
						if (lowerStr != 'png' && lowerStr !== 'jpg' && lowerStr !== 'jpeg') {
							uni.showToast({
								title: '请上传PNG、JPG、JPEG格式的图片',
								icon: 'none',
								duration: 3000
							});
							return;
						}
						uni.showLoading({
							title: '上传中...'
						})
						if (res.tempFiles[0]['size'] < 5 * 1024 * 1024) { //图片小于5M不压缩，大于5M压缩
							that.uploadImgFile(res.tempFilePaths[0], res.tempFiles[0], type)
						} else {
							// console.log('error')
							uni.compressImage({
								src: res.tempFilePaths[0],
								quality: 80,
								success: res => {
									// console.log(res, '=========123');
									that.uploadImgFile(res.tempFilePath, that, type)
								}
							})
						}

					},
				})
			},
			// 图片上传提交
			async uploadImgFile(filePath, file, type) {
				let _data = await uploadFile(filePath, 'file', {

				})
				uni.hideLoading(_data)
				if (_data.status == 200) {
					uni.showToast({
						title: _data.msg,
						icon: 'none',
						duration: 2000
					});
					this.form.head_img = _data.data.file_path
				} else {
					uni.showToast({
						title: _data.masg,
						icon: 'none',
						duration: 2000
					});
				}
			},

			to(path) {
				navigateTo(path)
			},
		},

	}
</script>

