				line-height: 68rpx;
				font-size: 28rpx;
				color: #ffffff;
			}
		}

		.main {
			width: 100%;
			padding: 30rpx;
			background-color: #ffffff;
			border-radius: 20rpx;

			.form {
				width: 100%;

				.form-item {
